use std :: collections :: HashSet ; use convert_case :: { Case , Casing } ; use forge_api :: { ToolName , ToolsOverview } ; use crate :: info :: Info ; use pretty_assertions :: assert_eq ; use super :: * ; # [doc = " Truncates an error message to at most 80 characters for display."] # [doc = ""] # [doc = " If the message exceeds 80 characters, the first 77 characters are kept"] # [doc = " followed by \"...\". Uses character-based counting to avoid panicking on"] # [doc = " multi-byte UTF-8 strings."] fn truncate_error (error : & str) -> String { if error . chars () . count () > 80 { let truncated : String = error . chars () . take (77) . collect () ; format ! ("{truncated}...") } else { error . to_string () } }